from fractions import Fraction as Q
from math import factorial
def moment(d,t):
 return Q(0) if d%4 else Q(factorial(d),factorial(d//4))*(-t)**(d//4)
def term(k,g,r,t):
 return Q(0) if g<r else Q(factorial(g),factorial(g-r))*moment(k+g-r,t)
checks=0
for t in [Q(1),Q(1,2),Q(1,32),Q(7,9)]:
 for k in range(3):
  for g in range(16):
   rhs=term(k,g,3,t)
   if k:rhs+=3*k*term(k-1,g,2,t)
   if k>=2:rhs+=3*k*(k-1)*term(k-2,g,1,t)
   assert moment(k+g+1,t)==-4*t*rhs
   checks+=1
 for g in range(16):
  assert moment(3+g,t)==-24*t*term(0,g,1,t)+144*t*t*term(0,g,5,t)-64*t**3*term(0,g,9,t)
  checks+=1
print(dict(exact_rational_signed_moment_tests=checks,passed=True,scope='Independent polynomial normalization tests, not a continuum reconstruction proof'))
